const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define western and eastern basin geometries for Lake Erie
  const westernBasin = ee.Geometry.Point([-83.3, 41.7]).buffer(15000);
  const easternBasin = ee.Geometry.Point([-79.8, 42.3]).buffer(15000);

  const targetDate = '2017-09-24';
  const startDate = '2017-09-23';
  const endDate = '2017-09-25';

  // Try Sentinel-2 first (better resolution for water quality)
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(startDate, endDate)
    .filterBounds(westernBasin.union(easternBasin))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let size = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${size}`);

  // If no Sentinel-2, try Landsat 8
  if (size === 0) {
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(westernBasin.union(easternBasin))
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    size = collection.size().getInfo();
    console.log(`Landsat 8 images found: ${size}`);

    if (size === 0) {
      console.log('No images found for the date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Process based on collection type
  let processedImage;
  const collectionName = collection.first().get('system:index').getInfo();

  if (collectionName.includes('COPERNICUS')) {
    // Sentinel-2: Calculate chlorophyll-a proxy using Red Edge bands
    const cloudMask = function(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    };

    processedImage = collection.map(cloudMask).median();
    // Chlorophyll proxy: B5/B4 ratio (Red Edge / Red)
    processedImage = processedImage.expression(
      'B5 / B4',
      {
        'B5': processedImage.select('B5'),
        'B4': processedImage.select('B4')
      }
    ).rename('chla_proxy');

  } else {
    // Landsat 8: Use NDVI as phytoplankton biomass proxy
    const cloudMask = function(image) {
      const qa = image.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0)
        .and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(mask)
        .multiply(0.0000275).add(-0.2);
    };

    processedImage = collection.map(cloudMask).median();
    processedImage = processedImage.normalizedDifference(['SR_B5', 'SR_B4'])
      .rename('chla_proxy');
  }

  // Calculate statistics for western basin
  const westernStats = processedImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: westernBasin,
    scale: 3000,
    maxPixels: 1e9
  });

  const westernMean = westernStats.get('chla_proxy_mean').getInfo();
  const westernCount = westernStats.get('chla_proxy_count').getInfo();

  // Calculate statistics for eastern basin
  const easternStats = processedImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: easternBasin,
    scale: 3000,
    maxPixels: 1e9
  });

  const easternMean = easternStats.get('chla_proxy_mean').getInfo();
  const easternCount = easternStats.get('chla_proxy_count').getInfo();

  console.log(`Western Basin - Mean: ${westernMean}, Pixels: ${westernCount}`);
  console.log(`Eastern Basin - Mean: ${easternMean}, Pixels: ${easternCount}`);

  // Validation checks
  if (westernCount === 0 || easternCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (westernMean === null || easternMean === null || 
      isNaN(westernMean) || isNaN(easternMean)) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare biomass proxy values
  if (westernMean > easternMean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
